mapper.select:
SELECT * FROM
(
SELECT A.*, ROWNUM RN
FROM (
select rw.id,rw.rwbt,rw.rwnr,rw.jzrq,rw.wcrq,rw.cjrq,rw.lxdh,rw.swry_dm as swryDm,rw.swjg_dm as swjgDm,rw.swjg_mc as swjgMc,
rw.swry_mc as swryMc,rw.rwzt_dm as rwztDm,rw.thyy,rw.ywqx,rw.rwly,rw.rwlx_dm as rwlxDm,rw.ywgjz,rw.bz,
dj.qyhgdm,dj.nsrmc,
sb.sbywb_dm as sbywbDm,sb.sssq,sb.sbpc,
(select dname from sys_dict y where sb.sbzl_dm=y.dcode and  y.dtype='ywlx_dm') as sbywbMc,
(select dname from sys_dict yy where rw.rwzt_dm=yy.dcode and  yy.dtype='rwzt_dm') as rwztMc
from RW_RWTXB  rw,SB_SBXX_HZ sb,GS_DJ_CKTMSDAB dj
where rw.YWGJZ=sb.ID and SB.NSRDZDAH= dj.NSRDZDAH and sb.qybj='Y'

	and rw.ywgjz=#{ywgjz}


	and rw.swjg_dm=#{swjgDm}


	and rw.rwzt_dm=#{rwztDm}


	and rw.ywlx_dm=#{ywlxDm}


	and rw.rwlx_dm=#{rwlxDm}


	and rw.rwly=#{rwly}


	and sb.sbzt_dm=#{sbztDm}


	and rw.swry_dm=#{czryDm}
 order by rw.cjrq desc
) A
)
WHERE 1=1

	and RN >= #{start}


	and RN <= #{end}

select count(*)
from RW_RWTXB  rw,SB_SBXX_HZ sb,GS_DJ_CKTMSDAB dj
where rw.YWGJZ=sb.ID and SB.NSRDZDAH= dj.NSRDZDAH and sb.qybj='Y'

	and rw.ywgjz=#{ywgjz}


	and rw.swjg_dm=#{swjgDm}


	and rw.rwzt_dm=#{rwztDm}


	and rw.ywlx_dm=#{ywlxDm}


	and rw.rwlx_dm=#{rwlxDm}


	and rw.rwly=#{rwly}


	and sb.sbzt_dm=#{sbztDm}


	and rw.swry_dm=#{czryDm}

SELECT dab.nsrsbh,dab.SHXYNO shxydm FROM gs_dj_cktmsdab dab ,sb_sbxx_hz hz
WHERE dab.nsrdzdah=hz.nsrdzdah
and hz.id=#{sbid}

select nsrsbh,concacts,tel
from tl_admin.edoc_apply
where nsrsbh = #{nsrsbh,jdbcType=VARCHAR}

sql.where:
pt.lcslid = #{lcslid,jdbcType=BIGINT}


	and pt.sbxh = #{sbxh,jdbcType=VARCHAR}





		and pt.glh = #{glh,jdbcType=VARCHAR}




	and pt.CKSP_DM = #{spdm,jdbcType=VARCHAR}



	and pt.ckbgdh = #{ckbgdh,jdbcType=VARCHAR}



	and h.hggqka_dm = #{hgcode,jdbcType=VARCHAR}




		and jh.ghfnsrsbh_1 = #{ghfnsrsbh,jdbcType=VARCHAR}





		and (pt.WTDBTSSCQYSHXYDM = #{wtqynsrsbh,jdbcType=VARCHAR} or pt.WTDBTSSCQYNSRSBH = #{wtqynsrsbh,jdbcType=VARCHAR})





		and pt.jhpzh = #{jhpzh,jdbcType=VARCHAR}


		and jh.jhpzh = #{jhpzh}









				AND pt.sbxh IN

					#{item}




				AND (



						pt.sbxh IN

							#{item}




						jh.sbxh
						IN

							#{item}




						pt.sbxh IN

							#{item}

						or
						jh.sbxh IN

							#{item}



						1 =1


				)





				and


						pt.LRRQ>=DATE'2026-04-01'
						AND pt.TSSWJG_DM_1 NOT LIKE '13307%'
						AND h.SBDWDM LIKE '33189%'





						pt.CKSP_DM like  #{item.yjObject,jdbcType=VARCHAR} || '%'


						pt.CKSP_DM = #{item.yjObject,jdbcType=VARCHAR}


						pt.CKSP_DM = #{item.yjRecord} and




						pt.ckbgdh like #{item.yjObject}|| '%'




								(pt.ckbgdh like #{item.yjObject}|| '%' or pt.dlzmh like #{item.yjObject}|| '%')


								(pt.ckbgdh like #{item.yjObject}|| '%' or pt.dlckhwzmhm like #{item.yjObject}|| '%')






						h.hggqka_dm = #{item.yjObject,jdbcType=VARCHAR}



						pt.sbxh = #{item.yjRecord,jdbcType=VARCHAR}




								(jh.GHFNSRSBH_1 = #{item.yjObject,jdbcType=VARCHAR} or pt.CKSP_DM like  #{item.yjObject,jdbcType=VARCHAR} || '%')


								 pt.CKSP_DM like  #{item.yjObject,jdbcType=VARCHAR} || '%'









								jh.GHFNSRSBH_1 = #{item.yjObject,jdbcType=VARCHAR}


								1 =1

mapper.select:
select main.* from( select 0 as sbid, pt.sbxh, pt.ckfph, pt.ckbgdh, pt.dlckhwzmhm as dlzmh, pt.ckrq_1 as ckrq, pt.cksp_dm as spdm, pt.sbsp_dm as spdmsb, pt.hgjldwmc as jldw, pt.cksl, pt.mylaj, pt.rmblaj, pt.zssl, pt.tsl, pt.jljgszch as jgmysch, pt.jsfpl as fplvJh, pt.mdtsbdmzhdkse as ztsceHw, pt.mdtse as mdtseHw, pt.cktmsywlxmcjh as ywlxmc, pt.ckhth as jckhth, h.hggqka_dm as hgcode, h.hggqka_dm as hgcodeName, h.mygdqsz_dm as gbcode, h.mygdqsz_dm as gbcodeName, pt.bz, nvl(h.hgspmc, pt.sbhgspmc) as spmc, g.gzxx,pt.djxh from hx_ckts.ckts_sb_mdt_tssb_gcb pt left join hx_ckts.ckts_wbsj_hg_bgd201 h on h.djxh = pt.djxh and h.ckbgdh = pt.ckbgdh left join ZJ_BJTS.yj_bgdgzxx_gcb g on g.djxh = pt.djxh and g.ckbgdh = pt.ckbgdh
) main
order by main.${orderSql}
order by main.sbxh

select main.* from ( select pt.lcslid,pt.ckbgdh, 0 as sbid, pt.sbxh, pt.glh, pt.ckfph, pt.dlzmh, pt.ckrq_1 as ckrq, pt.cksp_dm as spdm, pt.sbhgspmc as spmc, pt.hgjldwmc as jldw, pt.cksl, pt.mylaj, round(pt.mylaj * hl.rmbhl / 100,2) as zrmbxse, decode(pt.mylaj,null,0,0,0, round((pt.mylaj * hl.rmbhl / 100 - (select sum(s.jsje * (100 + zssl - tsl) /100) from hx_ckts.CKTS_SB_MTS_TSJH_GCB s where djxh=pt.djxh and glh=pt.glh)) / pt.mylaj,2)) as mmyllr, pt.cktmsywlxmcjh as ywlxmc, h.ckhth as jckhth, h.hggqka_dm as hgcode, h.hggqka_dm as hgcodeName, h.mygdqsz_dm as gbcode, h.mygdqsz_dm as gbcodeName, h.hzdwdq_dm as hzdwdqdm, h.hzdwdq_dm as hzdwdqdmName, pt.bz, decode(jh.sz,'V','增值税','C','消费税') as sz, jh.jhpzh, jh.ghfnsrsbh_1 as ghfnsrsbh, jh.kprq, jh.SBHGSPMC as spmcJh, jh.sl, jh.jsje, jh.zssl, jh.tsl, jh.tse, jh.sbxh as sbxhJh, g.gzxx,pt.djxh from hx_ckts.CKTS_SB_MTS_TSSB_GCB pt inner join hx_ckts.CKTS_SB_MTS_TSJH_GCB jh on (pt.djxh = jh.djxh and pt.glh = jh.glh) left join hx_cs_zdy.cs_ckts_hl hl on hl.hbzm_dm='USD' and hl.hlny=to_char(pt.ckrq_1,'yyyymm') left join hx_ckts.ckts_wbsj_hg_bgd201 h on h.djxh = pt.djxh and h.ckbgdh = pt.ckbgdh left join ZJ_BJTS.yj_bgdgzxx_gcb g on g.djxh = pt.djxh and g.ckbgdh = pt.ckbgdh
) main
order by main.${orderSql}
order by main.sbxh,main.sbxhJh

select (case when pt.sz='V' then '增值税' else '消费税' end) as sz,jhpzh,GHFNSRSBH_1 as ghfnsrsbh,
       kprq,SBHGSPMC as spmcJh,sl,jsje,zssl,tsl,tse,sbxh
from CKTS_SB_MTS_TSJH_LSB pt
where sbid = #{sbid,jdbcType=BIGINT}
  and glh = #{glh,jdbcType=VARCHAR}

	  and GHFNSRSBH_1 = #{ghfnsrsbh,jdbcType=VARCHAR}

order by sbxh

select main.* from( select 0 as sbid, pt.sbxh, nvl(pt.WTDBTSSCQYSHXYDM, pt.WTDBTSSCQYNSRSBH) as wtqynsrsbh, pt.ckbgdh, pt.CKRQ_1 as ckrq, pt.CKSP_DM as spdm, pt.HGSPMC as spmc, pt.SBSP_DM as spdmSb, pt.HGJLDWMC as jldw, pt.cksl, pt.mylaj, pt.DBTSWSPZHM as jhpzh, pt.kprq, pt.jsje, pt.zssl, pt.tsl, pt.tse, pt.CKTMSYWLXMCJH as ywlxmc, pt.DBTSYWLXMC as hwlx, h.hggqka_dm as hgcode, h.hggqka_dm as hgcodeName, h.mygdqsz_dm as gbcode, h.mygdqsz_dm as gbcodeName, h.hzdwdq_dm as hzdwdqdm, h.hzdwdq_dm as hzdwdqdmName, pt.bz from hx_ckts.CKTS_SB_DB_TSSB_GCB pt left join hx_ckts.ckts_wbsj_hg_bgd201 h on h.djxh = pt.djxh and h.ckbgdh = pt.ckbgdh
) main
order by main.${orderSql}
order by main.sbxh

select main.* from( select 0 as sbid, pt.sbxh, pt.gjzyhwmc, (case when pt.JHPZZL_DM = '1' then '增值税专用发票' else '增值税普通发票' end) as pzzldm, pt.jhpzh, pt.kprq, pt.GHFNSRSBH_1 as ghfnsrsbh, pt.HGJLDWMC as jldw, pt.sl, pt.dj, pt.jsje, pt.se, pt.zssl, pt.tse, pt.FKPZHM as fkpzh, pt.CKTMSYWLXMCJH as ywlxmc, pt.bz from hx_ckts.CKTS_SB_GJ_SBMX_GCB pt
) main
order by main.${orderSql}
order by main.sbxh

select lxrdh
from tl_admin.sys_user
where czry_dm = #{czryDm,jdbcType=VARCHAR}

		select main.* from (
			select id,sbnypc,entry_id as entryId,status,release_time as releaseTime,back_count as backCount,
		    (case when yjsl>0 then '是' else '否' end)  as yjbz
			from tl_admin.edoc_examine_business pt
		where   pt.swjgdm like  #{swjgdm,jdbcType=VARCHAR}||'%'
		        and pt.nsrsbh = #{nsrsbh,jdbcType=VARCHAR}
		        and pt.sbnypc =  #{sbnypc,jdbcType=VARCHAR}

                 and pt.status <> '0'


                   and (pt.releaser =  #{releaser,jdbcType=VARCHAR})


				and nvl(pt.void_flag,'0') = '0'
		) main

			order by main.${orderSql}


			order by main.sbnypc desc

select * from shzs_wp_task t
where swjgdm=#{swjgDm}

	and (nsrmc like '%'||#{dto.qybs}||'%' or nsrsbh like '%'||#{dto.qybs}||'%')


	and (wpdx like '%'||#{dto.wpdx}||'%' or wpsfdm like '%'||#{dto.wpdx}||'%')


	and swsxdm = #{dto.swsxdm}


	and status = #{dto.status}


	and status = #{dto.status}


	and wpsj>#{dto.wpsjStart}


	and #{dto.wpsjEnd}>wpsj


	order by ${dto.orderSql}
